      SELECT "id", "out_sum", "fees", "tx_count", "blk_count", "no", "start_time", "end_time"
        FROM "epoch_finalized"
        WHERE (SELECT enabled FROM "epoch_sync_enabled" WHERE singleton = TRUE)
      UNION ALL
      SELECT "id", "out_sum", "fees", "tx_count", "blk_count", "no", "start_time", "end_time"
        FROM "epoch_current" ;

